static class Program {
 static int checks;static void Check(bool condition,string reason){if(!condition)throw new Exception(reason);Console.WriteLine($"PASS {++checks}: {reason}");}
 static Dictionary<string,JsonElement> Params(BranchStringPlugin p,string rows)=>new(p.Descriptor.Parameters.ToDictionary(x=>x.Name,x=>x.DefaultValue!.Value.Clone())){["ModuleInfoList"]=JsonSerializer.SerializeToElement(rows)};
 static long Status(ModuleResult result)=>result.Outputs["ModuStatus"].As<long>();static string Match(ModuleResult result)=>result.Outputs["BranchMatch"].As<string>();
 [STAThread]static int Main(){try{_=new Application();Run();Console.WriteLine($"PASS {checks} production BranchString checks; original runtime not executed");return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}finally{Application.Current?.Shutdown();}}
 static void Run(){var plugin=new BranchStringPlugin();var runtime=plugin.CreateRuntime();
  ModuleResult Execute(string input,string rows="a#alpha#0$b#beta#0$",IReadOnlyList<ExecutionSuccessor>? next=null)=>runtime.ExecuteAsync(new("branch",Environment.CurrentDirectory,new Dictionary<string,PortValue>{{"StringA",PortValue.Text(input)}},Params(plugin,rows)){ExecutionSuccessors=next??[new("a",101),new("b",102)]},default).Result;
  var one=Execute("alpha");Check(Status(one)==1&&Match(one)=="ID101;"&&one.SelectedExecutionSuccessors!.SequenceEqual(new[]{"a"}),"ordinary full byte-equal text selects mapped numeric target");Check(Status(Execute("Alpha"))==0&&Match(Execute("Alpha"))=="No Module","comparison is case-sensitive");Check(Status(Execute("alp"))==0&&Status(Execute("alpha "))==0,"prefix/whitespace are not full matches");Check(Match(Execute("alpha","b#alpha#0$a#alpha#0$"))=="ID102;ID101;","all matching rows preserve configured order");Check(Match(Execute("ignored","a#not-equal#1$b#beta#0$"))=="(D)ID101;","exact debug flag1 bypasses comparison and adds source marker");Check(Match(Execute("ignored","gone#not-equal#1$"))=="(D)"&&Status(Execute("ignored","gone#not-equal#1$"))==1&&Execute("ignored","gone#not-equal#1$").SelectedExecutionSuccessors!.Count==0,"debug marker alone gives status1 even without matching connected target");Check(Match(Execute("ignored","a#not-equal#2$"))=="No Module","flag2 is not treated as debug true");Check(Match(Execute("alpha",next:[]))==""&&Status(Execute("alpha",next:[]))==0,"zero actual successors retains empty BranchMatch rather than No Module");Check(Match(Execute("alpha",""))=="No Module","nonempty successor list with no rows reports No Module");Check(Match(Execute("","a##0$b#beta#0$"))=="ID101;","normal empty text has Frame outLen1 and matches default empty row");Check(Match(Execute("","a#other#1$"))=="(D)ID101;","empty text can enter debug branch because length includes NUL");Check(Match(Execute("中文","a#中文#0$"))=="ID101;","valid UTF8 exact text equality retained");Check(Execute("alpha\0ignored").Outputs["StringMatch"].As<string>()=="alpha"&&Status(Execute("alpha\0ignored"))==1,"input frame NUL termination retained");
  var array=runtime.ExecuteAsync(new("branch",Environment.CurrentDirectory,new Dictionary<string,PortValue>{{"StringA",PortValue.TextArray(["alpha","beta"])}},Params(plugin,"a#alpha#0$b#beta#0$")){ExecutionSuccessors=[new("a",101),new("b",102)]},default).Result;Check(Match(array)=="ID101;","text array caller reads only index0");
  Check(Execute(new string('x',255)).Status==ModuleStatus.Success,"single capacity256 read accepts255 ASCII bytes plus NUL");Check(Execute(new string('x',256)).NativeErrorCode==0xe0000012,"single capacity256 read rejects256 ASCII bytes without retry");Check(Execute(new string('中',85)).Status==ModuleStatus.Success&&Execute(new string('中',86)).NativeErrorCode==0xe0000012,"capacity is UTF8 bytes rather than UTF16 length");
  var unmapped=Execute("alpha",next:[new("a")]);Check(Match(unmapped)=="NodeId:a;"&&unmapped.Message!.Contains("Independent"),"unmapped identity explicitly uses independent NodeId format");
  using(var scope=new ModuleExecutionScope()){var reader=new Reader(new(0,3,"alpha",6));scope.RegisterService<IToolTextInputReader>(reader);ModuleResult Run()=>runtime.ExecuteAsync(new("branch",Environment.CurrentDirectory,new Dictionary<string,PortValue>{{"StringA",PortValue.Text("wrong")}},Params(plugin,"a#alpha#0$")){Scope=scope.ForProcedure("p"),ExecutionSuccessors=[new("a",101)],ReadTextInput=(_,_,_)=>throw new Exception("scope priority")},default).Result;Check(Status(Run())==1&&reader.Calls.SequenceEqual(new[]{"StringA:0:256"}),"scope text reader highest priority with exact source single read");foreach(uint error in new[]{0xe0000314u,0xe0000012u,0xe0000014u}){reader.Result=new(error,9,"alpha",6);reader.Calls.Clear();var result=Run();Check(result.NativeErrorCode==error&&result.Outputs.Count==0&&result.SelectedExecutionSuccessors!.Count==0&&reader.Calls.Count==1,"source read error clears routes and produces no outputs without retry "+error.ToString("x"));}reader.Result=new(0,0,"alpha",6);Check(Run().Status==ModuleStatus.Success&&Run().Outputs.Count==0,"explicit successful zero Count retains native early return");reader.Result=new(0,1,"alpha",0);Check(Match(Run())=="No Module"&&Status(Run())==0,"explicit successful zero outLen takes separate source length gate");}
  Check(BranchStringTable.Serialize(BranchStringTable.ApplySetter("a##0$"))=="a#0#0$","native strtok empty field shifts flag0 into text");Check(BranchStringTable.Serialize(BranchStringTable.ApplySetter("a##1$"))=="a#1#0$","native strtok empty field shifts debug1 into text and clears missing flag");Check(BranchStringTable.ReadCanonical("a##1$")[0] is {Text:"",DebugFlag:1},"GetParam canonical parser preserves empty field rather than invoking setter");Check(BranchStringTable.Serialize(BranchStringTable.ApplySetter("a#x#1"))=="a#x#1$","native setter accepts final unterminated row");var model=new BranchStringListModel();model.Read("a#x#1");Check(model.Rows.Count==0,"UI parser ignores unterminated final row");model.Read("a#x#1$b#y#0$");Check(!model.Rows[0].TrySetText(new string('x',31))&&!model.Rows[0].TrySetText("a#b")&&!model.Rows[0].TrySetText("a$b"),"UI exact UTF16 length and delimiter guards");Check(model.Rows[0].TrySetText(new string('中',30))&&model.Rows[0].Text.Length==30,"UI length guard counts characters, not UTF8 bytes");
  var node=new NodeDocument("branch",BranchStringPlugin.Id,"1.0.0","Branch",Params(plugin,"a#x#1$b#y#0$"));var updated=plugin.ApplyExecutionTopologyChange(node,[new("a"),new("b")],[new("a"),new("c")]);Check(updated.Parameters["ModuleInfoList"].GetString()=="a#x#1$c##0$","topology retains row text/flag/order and appends native empty default");Check(ReferenceEquals(plugin.ApplyExecutionTopologyChange(node,[new("a")],[new("a")]),node),"unchanged topology does not rebuild table");var thirtyTwo=Enumerable.Range(0,32).Select(i=>new ExecutionSuccessor("t"+i)).ToArray();bool cap=false;try{plugin.ApplyExecutionTopologyChange(node,thirtyTwo,thirtyTwo.Append(new("extra")).ToArray());}catch(InvalidOperationException){cap=true;}Check(cap,"source 32 successor gate");var copy=plugin.PrepareCopiedNode(node,node with{Id="copy"},new Dictionary<string,string>{{"b","B"}},[new("B")]);Check(copy.Parameters["ModuleInfoList"].GetString()=="B#y#0$","copied mapped rows preserve text/flag and exclude unmapped target");var emptyNode=node with{Parameters=Params(plugin,"a##0$")};Check(plugin.PrepareCopiedNode(emptyNode,node with{Id="copy"},new Dictionary<string,string>{{"a","A"}},[new("A")]).Parameters["ModuleInfoList"].GetString()=="A#0#0$","copy writes mapped empty row through actual setter semantics");Check(plugin.PrepareCopiedNode(emptyNode,node with{Id="copy"},new Dictionary<string,string>(),[]).Parameters["ModuleInfoList"].GetString()=="","single-node copy has no stale targets");Check(plugin.PrepareRestoredNode(emptyNode).Parameters["ModuleInfoList"].GetString()=="a#0#0$","real restore provider applies saved GetParam through native setter");
  Configuration(plugin);Graph(plugin);Persistence(plugin);
 }
 static void Configuration(BranchStringPlugin plugin){int apply=0,run=0;var values=Params(plugin,"a#one#0$b#two#1$");var context=new ToolEditorContext(new("config",BranchStringPlugin.Id,"1.0.0","Config",values),Environment.CurrentDirectory,next=>{values=next;apply++;},_=>{run++;throw new Exception("no source run command");});using(var session=plugin.CreateConfiguration(context)){Check(session.State.Find("IndexUserSet") is null,"commented mode control is not instantiated");Check(session.State.Nodes.Count(n=>n.Element.Tag=="BottomCommand")==1&&!session.State.Nodes.Any(n=>n.Element.Tag.Contains("Execute")||n.Element.Tag.Contains("Reset")),"source only Confirm footer, no invented Run or Reset");using var view=new ToolConfigurationView(session.State,session.Controls,session.Language,session.Localize);view.Measure(new Size(420,500));view.Arrange(new Rect(0,0,420,500));view.UpdateLayout();Check(view.Diagnostics.Count==0,"all original source leaf templates instantiate in real WPF view");var boxes=Walk(view).OfType<TextBox>().Where(b=>b.Width==115).ToArray();Check(boxes.Length==2,"source text rows have115px input boxes");boxes[0].Text="changed";Check(values["ModuleInfoList"].GetString()=="a#changed#0$b#two#1$","real TextChanged writes model-backed value");int before=apply;boxes[0].Text=new string('x',31);Check(apply==before&&values["ModuleInfoList"].GetString()=="a#changed#0$b#two#1$","rejected text does not mutate backend");boxes[0].Text="";Check(values["ModuleInfoList"].GetString()=="a#0#0$b#two#1$"&&session.State.Find("ModuleInfoList")!.Value=="a##0$b#two#1$","empty accepted text canonicalizes backend while current UI retains attempt");var toggles=Walk(view).OfType<ToggleButton>().Where(t=>t.Margin.Left==15).ToArray();toggles[0].IsChecked=true;Check(values["ModuleInfoList"].GetString()=="a#1#0$b#two#1$"&&session.State.Find("ModuleInfoList")!.Value=="a##1$b#two#1$","debug toggle with empty UI text follows native empty-token shift");Check(run==0,"all source edits have no PreRun");bool closed=false;session.CloseRequested+=()=>closed=true;session.State.Invoke(session.State.Nodes.Single(n=>n.Element.Tag=="BottomCommand"));Check(closed,"source Confirm closes session");}
  using var reopened=plugin.CreateConfiguration(context with{Node=context.Node with{Parameters=values}});Check(reopened.State.Find("ModuleInfoList")!.Value=="a#1#0$b#two#1$","configuration reopen reads canonical backend text/flag");}
 static void Graph(BranchStringPlugin plugin){var modules=new ModuleRegistry();modules.Register(plugin.Descriptor,plugin.CreateRuntime);var sink=new ModuleDescriptor("test.string-sink","1","Sink",[new PortDescriptor("Text",DataKind.Text,false)],[],[]);modules.Register(sink,()=>new Sink(sink));var root=new NodeDocument("root",BranchStringPlugin.Id,"1.0.0","Root",Params(plugin,"left#alpha#0$right#beta#0$"));var graph=new ProcedureDocument("g","Graph",[root,new("left",sink.Id,"1","Left",new Dictionary<string,JsonElement>()),new("right",sink.Id,"1","Right",new Dictionary<string,JsonElement>())],[],[new("root","left"),new("root","right")]);using var scope=new ModuleExecutionScope();scope.RegisterService<IToolTextInputReader>(new Reader(new(0,1,"alpha",6)));var result=new GraphExecutor(modules).RunAsync(graph,Environment.CurrentDirectory,scope:scope.ForProcedure("g")).GetAwaiter().GetResult();Check(result.Nodes.Single(n=>n.NodeId=="left").Status==NodeRunStatus.Success&&result.Nodes.Single(n=>n.NodeId=="right").Status==NodeRunStatus.Skipped,"actual production Graph executes selected string branch only");var isolated=new GraphExecutor(modules).RunAsync(graph with{Nodes=[root],ExecutionLinks=[]},Environment.CurrentDirectory,scope:scope.ForProcedure("g"),executionSuccessorRead:_=>[new("left"),new("right")]).GetAwaiter().GetResult();Check(isolated.Nodes.Count==1&&isolated.Nodes[0].Outputs["BranchMatch"].As<string>()=="NodeId:left;","production isolated SelfRun sees true successors");var service=new WorkflowConfigurationSubscriptionService(()=>graph,modules,"left",(_,_)=>throw new Exception("forbidden binding"));var query=new ConfigurationSubscriptionQuery(new(ConfigurationSubscriptionDomain.InputIo,"Text","string"),["string"]);Check(service.Enumerate(query).Roots.SelectMany(n=>n.Children).All(n=>n.Binding?.Reference is not ConfigurationOutputReference r||r.NodeId!="root"),"string outputs forbidden by source metadata excluded from tree");Check(service.Bind(query.Destination,new(new ConfigurationOutputReference("g","root","BranchMatch","string"),ConfigurationSubscriptionIndex.All)).Status!=ConfigurationSubscriptionStatus.Available,"forged forbidden string binding rejected");}
 static void Persistence(BranchStringPlugin plugin){var modules=new ModuleRegistry();var plugins=new ToolPluginRegistry();plugins.Register(plugin,modules);var editor=new GraphEditorDocument(modules);editor.PrepareLoad=plugins.PrepareLoad;editor.PrepareSave=(d,b)=>plugins.PrepareSave(d,b);string id=editor.AddNode(BranchStringPlugin.Id,"1.0.0",0,0);editor.SetParameters(id,Params(plugin,"target##0$"));string path=System.IO.Path.GetFullPath("analysis/b-string/solution/string.vsolution");System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(path)!);editor.Save(path);Check(editor.CurrentProcedure.Nodes.Single().Parameters["ModuleInfoList"].GetString()=="target##0$","Save does not prematurely apply Load setter roundtrip");editor.Load(path);Check(editor.CurrentProcedure.Nodes.Single().Parameters["ModuleInfoList"].GetString()=="target#0#0$","actual file Load optional provider roundtrips empty default");editor.SetParameters(id,Params(plugin,"target#text#1$"));editor.Save(path);editor.Load(path);Check(editor.CurrentProcedure.Nodes.Single().Parameters["ModuleInfoList"].GetString()=="target#text#1$","nonempty row text and flag persist unchanged");}
 static IEnumerable<DependencyObject> Walk(DependencyObject value){yield return value;for(int i=0;i<VisualTreeHelper.GetChildrenCount(value);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(value,i)))yield return child;}
 sealed class Reader(ToolTextInputReadResult result):IToolTextInputReader{public ToolTextInputReadResult Result=result;public List<string> Calls=[];public ToolTextInputReadResult Read(ModuleExecutionContext context,string name,int index,int capacity){Calls.Add(name+":"+index+":"+capacity);return Result;}}
 sealed class Sink(ModuleDescriptor descriptor):IModule{public ModuleDescriptor Descriptor=>descriptor;public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext context,CancellationToken cancellationToken)=>ValueTask.FromResult(new ModuleResult(ModuleStatus.Success,new Dictionary<string,PortValue>()));}
